package io.github.kpaakeh.smog.copper;

import java.util.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.Container;
import net.minecraft.world.item.*;
import io.github.kpaakeh.smog.registry.ModBlocks;

/** Forms are generated by shape, never by the metal of the sampled head. */
public final class MoldMaking {
    public static String pattern(ItemStack sample){
        var part=ToolDefinitions.part(sample);if(part==null)part=ToolParts.nativeSource(sample);
        if(part!=null&&part.form().category().equals("head")&&!part.cast())return part.form().id().replaceFirst("_head$","");
        String name=BuiltInRegistries.ITEM.getKey(sample.getItem()).getPath();if(name.endsWith("_ingot"))return "ingot";if(name.endsWith("_plate"))return "plate";if(name.endsWith("_fitting"))return "fitting";if(name.endsWith("_pipe_part"))return "pipe";return null;
    }
    private static ItemStack mold(String prefix,String shape){var id=ModBlocks.id(prefix+shape+"_mold");return BuiltInRegistries.ITEM.containsKey(id)?new ItemStack(BuiltInRegistries.ITEM.getValue(id)):ItemStack.EMPTY;}
    public static ItemStack metalMold(String shape){return mold("metal_",shape);}
    public static ItemStack sandMold(String shape){return mold("sand_",shape);}
    public static ItemStack preview(Container inventory){
        if(!inventory.getItem(5).isEmpty()||!CopperWorkshops.is(inventory.getItem(0),"smog:molding_sand"))return ItemStack.EMPTY;
        for(int n=2;n<ToolDefinitions.maxParts();n++)if(!inventory.getItem(ToolDefinitions.slot(n)).isEmpty())return ItemStack.EMPTY;
        String shape=pattern(inventory.getItem(1));return shape==null?ItemStack.EMPTY:sandMold(shape);
    }
}
